<script setup>
import { money, initials, dateLabel } from '#shared/utils/format.js'
defineProps({ orders: Array, compact: Boolean, hidePrice: Boolean })
</script><template><div class="table-wrap"><table><thead><tr><th>Order / Customer</th><th>Treatment</th><th>Jadwal</th><th v-if="!compact">Lokasi</th><th>Therapist</th><th>Status</th><th v-if="!hidePrice">Total</th><th /></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td><NuxtLink :to="'/orders/'+order.id" class="customer-cell"><span class="avatar pastel">{{ initials(order.customerName) }}</span><span><strong>{{ order.customerName }}</strong><small>{{ order.orderNumber }}</small></span></NuxtLink></td><td><strong class="table-main">{{ order.items.map(i => i.serviceNameSnapshot).join(', ') }}</strong><small class="table-sub">{{ order.items.reduce((n,i) => n+i.durationMinutes*i.qty,0) }} menit</small></td><td><strong class="table-main">{{ order.bookingTime.slice(0,5) }}</strong><small class="table-sub">{{ dateLabel(order.bookingDate) }}</small></td><td v-if="!compact"><span class="location-cell"><UiIcon name="locations" :size="13" />{{ order.locationName || 'Belum ditetapkan' }}</span></td><td><span v-if="order.assignment" class="therapist-cell"><span class="avatar tiny">{{ initials(order.assignment.therapistName) }}</span>{{ order.assignment.therapistName.split(' ')[0] }}</span><span v-else class="muted">Belum ditetapkan</span></td><td><UiBadge :status="order.orderStatus" /></td><td v-if="!hidePrice" class="table-price">{{ money(order.total) }}</td><td><NuxtLink :to="'/orders/'+order.id" class="icon-button" :aria-label="'Lihat '+order.orderNumber"><UiIcon name="right" :size="17" /></NuxtLink></td></tr></tbody></table><UiEmptyState v-if="!orders?.length" title="Tidak ada order" message="Tambahkan order baru atau sesuaikan filter Anda." /></div></template>